"""Renders data/schema.md. Imported by build_dataset.py; all numbers come from the build."""
import json


def _table(headers, rows):
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    for r in rows:
        out.append("| " + " | ".join(str(c).replace("|", "/") for c in r) + " |")
    return "\n".join(out)


def _fields(rows):
    return _table(["field", "type", "meaning"], rows)


def render(cur, st, example, rec, activities, recs, rank):
    W = cur["weights"]
    R = W["runtime"]
    acts = {a["id"]: a for a in activities}
